import{_ as n,o as h,c as d,a3 as i}from"./chunks/framework.MGD2uYU7.js";const l=JSON.parse('{"title":"BRD — Business Requirements Document","description":"","frontmatter":{},"headers":[],"relativePath":"guide/01-brd.md","filePath":"guide/01-brd.md","lastUpdated":null}'),a={name:"guide/01-brd.md"};function e(o,t,r,c,g,u){return h(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="brd-—-business-requirements-document" tabindex="-1">BRD — Business Requirements Document <a class="header-anchor" href="#brd-—-business-requirements-document" aria-label="Permalink to &quot;BRD — Business Requirements Document&quot;">​</a></h1><p><strong>Dự án</strong>: AnPhucRealEstate — Nền tảng mua bán &amp; đấu giá nhà ở xã hội (NOXH) <strong>Status</strong>: In Review <strong>Author</strong>: Alex (Product Manager) — <strong>Last updated</strong>: 2026-10-09 — <strong>Version</strong>: 1.1 (review pass: thêm OQ-9 Figma, non-goal reset mật khẩu, rủi ro email deliverability) <strong>Stakeholders</strong>: Ban điều hành An Phuc, Tech Lead, Eng Leads (BE/FE/Mobile), Design Lead, QA Lead, Pháp chế, Ops/Quản trị nội dung, CS <strong>Tài liệu liên quan</strong>: chuỗi doc <code>docs/02</code> → <code>docs/10</code>. File nguồn nghiệp vụ chưa số hóa: <code>1. Hiện trạng phân mồi, web quản trị kinh doanh.xlsx</code> (người dùng cung cấp) — <strong>phải được BA/Ops bóc tách và hợp nhất vào doc này trước khi Approved</strong> (xem OQ-0).</p><hr><h2 id="_1-tom-tat-đieu-hanh-executive-summary" tabindex="-1">1. Tóm tắt điều hành (Executive Summary) <a class="header-anchor" href="#_1-tom-tat-đieu-hanh-executive-summary" aria-label="Permalink to &quot;1. Tóm tắt điều hành (Executive Summary)&quot;">​</a></h2><p>AnPhucRealEstate là nền tảng web (API-first) cho phép <strong>chủ sở hữu nhà ở xã hội đăng bán</strong>, <strong>người mua đấu giá công khai</strong> và <strong>An Phuc vận hành minh bạch</strong> toàn bộ phiên đấu giá, thanh toán, xác minh pháp lý.</p><p>Giá trị cốt lõi: <strong>minh bạch giá + xác minh pháp lý (sổ hồng/đỏ, CCCD) + đấu giá có kiểm soát</strong> — thay thế quy trình giấy tờ bất minh, nhiều cò mồi và lừa đảo hiện nay.</p><p><strong>Phiên bản 1 (v1) KHÔNG bao gồm đề xuất/gợi ý bằng AI</strong> — toàn bộ tính năng AI (gợi ý căn hộ, định giá tự động, chấm điểm ảnh) được để dành cho v2 (xem §8 Non-Goals).</p><hr><h2 id="_2-bai-toan-kinh-doanh-problem-statement" tabindex="-1">2. Bài toán kinh doanh (Problem Statement) <a class="header-anchor" href="#_2-bai-toan-kinh-doanh-problem-statement" aria-label="Permalink to &quot;2. Bài toán kinh doanh (Problem Statement)&quot;">​</a></h2><h3 id="_2-1-boi-canh" tabindex="-1">2.1 Bối cảnh <a class="header-anchor" href="#_2-1-boi-canh" aria-label="Permalink to &quot;2.1 Bối cảnh&quot;">​</a></h3><ul><li>Chương trình 1 triệu căn NOXH đến 2030 của Chính phủ → nguồn cung thứ cấp (mua đi bán lại) tăng nhanh trong khi hạ tầng giao dịch chính thống gần như bằng 0.</li><li>Giao dịch NOXH hiện tại phụ thuộc: bảng tin giấy tại dự án, nhóm Facebook/Zalo, môi giới tự phát; hồ sơ mua bán nhà ở xã hội theo Luật Nhà ở 2023 / Nghị định 100/2024/CP yêu cầu điều kiện người mua nghiêm ngặt nhưng <strong>không có công cụ xác minh tập trung</strong>.</li><li>File hiện trạng nội bộ (&quot;Hiện trạng phân mồi, web quản trị kinh doanh.xlsx&quot;) ghi nhận quy trình thủ công và hệ thống quản trị cũ — cần bóc tách làm baseline (OQ-0).</li></ul><h3 id="_2-2-chi-phi-cua-viec-khong-giai-quyet" tabindex="-1">2.2 Chi phí của việc không giải quyết <a class="header-anchor" href="#_2-2-chi-phi-cua-viec-khong-giai-quyet" aria-label="Permalink to &quot;2.2 Chi phí của việc không giải quyết&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Đối tượng</th><th>Nỗi đau</th><th>Chi phí / hậu quả</th></tr></thead><tbody><tr><td>Người mua</td><td>Không biết giá thật, sợ mua trúng nhà không đủ điều kiện pháp lý, bị &quot;cò&quot; thu phí ngầm</td><td>Mất cọc, giao dịch hỏng, rủi ro pháp lý kéo dài</td></tr><tr><td>Chủ nhà (người bán)</td><td>Đăng tin thủ công từng nơi, giá bị ép bởi môi giới, không có công cụ tìm người mua thật</td><td>Thời gian bán trung bình nhiều tháng, chi phí môi giới 1–2% giá bán</td></tr><tr><td>Sàn An Phuc</td><td>Giao dịch nằm ngoài tầm kiểm soát, doanh thu phụ thuộc môi giới offline</td><td>Không mở rộng được, thương hiệu rủi ro</td></tr><tr><td>Cơ quan quản lý dự án</td><td>Khó kiểm chứng người mua đủ điều kiện NOXH</td><td>Rủi ro pháp lý khi chuyển nhượng bị hủy</td></tr></tbody></table><h3 id="_2-3-bang-chung-ban-đau-can-bo-sung-truoc-approved" tabindex="-1">2.3 Bằng chứng ban đầu (cần bổ sung trước Approved) <a class="header-anchor" href="#_2-3-bang-chung-ban-đau-can-bo-sung-truoc-approved" aria-label="Permalink to &quot;2.3 Bằng chứng ban đầu (cần bổ sung trước Approved)&quot;">​</a></h3><ul><li>Tổng hợp hiện trạng từ file xlsx nội bộ (OQ-0).</li><li>Phỏng vấn 5 chủ nhà + 5 người mua NOXH tại dự án trọng điểm — <strong>chưa thực hiện, điều kiện bắt buộc trước khi khóa scope</strong> (Discovery Phase 1).</li><li>Cạnh tranh: Chotot/Nhatot nhà đất có đăng tin nhưng <strong>không có</strong> đấu giá có kiểm soát, không xác minh CCCD–sổ hồng chéo, không giới hạn giá trần NOXH.</li></ul><hr><h2 id="_3-muc-tieu-kpi" tabindex="-1">3. Mục tiêu &amp; KPI <a class="header-anchor" href="#_3-muc-tieu-kpi" aria-label="Permalink to &quot;3. Mục tiêu &amp; KPI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Mục tiêu (Outcome)</th><th>Metric</th><th>Baseline (10/2026)</th><th>Target</th><th>Measurement window</th></tr></thead><tbody><tr><td>G1</td><td>Tạo được nguồn cung được xác minh</td><td>Tin đăng APPROVED/LISTED</td><td>0</td><td>≥ 300 trong 90 ngày sau GA</td><td>90 ngày</td></tr><tr><td>G2</td><td>Giao dịch đấu giá thành công</td><td>Tỷ lệ phiên AWARDED có người mua thanh toán đủ (COMPLETED)</td><td>0</td><td>≥ 60% trên ≥ 10 phiên</td><td>1 quý</td></tr><tr><td>G3</td><td>Doanh thu</td><td>Tổng thu (phí đấu giá + gói VIP)</td><td>0</td><td>≥ 1,0 tỷ VND trong 2 quý đầu</td><td>2 quý</td></tr><tr><td>G4</td><td>Niềm tin / an toàn</td><td>Khiếu nại pháp lý sau giao dịch / tổng giao dịch</td><td>n/a</td><td>&lt; 2%</td><td>2 quý</td></tr><tr><td>G5</td><td>Chuyển đổi thành viên</td><td>% khách → đăng ký → KYC APPROVED</td><td>n/a</td><td>Đăng ký ≥ 1.000; KYC pass ≥ 70%</td><td>90 ngày</td></tr><tr><td>G6</td><td>Vận hành</td><td>Thời gian duyệt KYC / duyệt tin</td><td>thủ công</td><td>≤ 48h SLA, ≥ 90% đạt SLA</td><td>theo tháng</td></tr></tbody></table><p><strong>North Star Metric (v1)</strong>: <strong>GMV đấu giá hoàn tất (tổng giá trị settlement orders COMPLETED)</strong> — vì nó đồng thời chứng minh: đủ nguồn cung tin đăng, đủ cầu tham gia, và hệ thống tiền hoạt động.</p><hr><h2 id="_4-personas-cac-ben-lien-quan" tabindex="-1">4. Personas &amp; các bên liên quan <a class="header-anchor" href="#_4-personas-cac-ben-lien-quan" aria-label="Permalink to &quot;4. Personas &amp; các bên liên quan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Persona</th><th>Vai trò hệ thống</th><th>Mô tả</th><th>Nhu cầu chính</th></tr></thead><tbody><tr><td><strong>Khách</strong> (Guest)</td><td><code>GUEST</code></td><td>Chưa đăng nhập, tìm hiểu thị trường</td><td>Xem tin/phiên đấu giá công khai, tạo niềm tin trước khi đăng ký</td></tr><tr><td><strong>Anh Mua</strong> — người mua NOXH</td><td><code>USER</code> (thành viên)</td><td>28–45, thu nhập trung bình, đủ điều kiện NOXH, cần xác minh an toàn</td><td>Đủ điều kiện, giá minh bạch, quy trình cọc/thanh toán rõ ràng</td></tr><tr><td><strong>Chị Bán</strong> — chủ sở hữu</td><td><code>USER</code> (thành viên)</td><td>Sở hữu căn NOXH cần bán đúng luật, sợ bị ép giá</td><td>Đăng tin được duyệt nhanh, tiếp cận người mua thật, bán đấu giá hoặc thỏa thuận</td></tr><tr><td><strong>Ops An Phuc</strong> — quản trị viên</td><td><code>ADMIN</code></td><td>Nhân viên vận hành sàn: duyệt KYC, duyệt tin, tạo &amp; điều hành phiên đấu giá, xử lý thanh toán</td><td>Công cụ quản trị tập trung, audit đầy đủ, SLA rõ</td></tr><tr><td><strong>Pháp chế</strong></td><td>Stakeholder ngoài hệ thống</td><td>Review điều kiện mua NOXH, quy chế đấu giá, hợp đồng</td><td>Mọi quy tắc nghiệp vụ phải ghi thành văn bản (docs/08)</td></tr><tr><td><strong>Ban điều hành</strong></td><td>Sponsor</td><td>Phê duyệt ngân sách, mô hình doanh thu</td><td>KPI G1–G6, milestone plan (docs/10)</td></tr></tbody></table><p><strong>RACI cấp chương trình</strong>: R = PM (Alex) &amp; Tech Lead; A = Ban điều hành; C = Pháp chế, CS, Design; I = toàn công ty.</p><hr><h2 id="_5-pham-vi-scope" tabindex="-1">5. Phạm vi (Scope) <a class="header-anchor" href="#_5-pham-vi-scope" aria-label="Permalink to &quot;5. Phạm vi (Scope)&quot;">​</a></h2><h3 id="_5-1-lam-trong-v1-—-theo-module-bounded-context" tabindex="-1">5.1 Làm trong v1 — theo module (bounded context) <a class="header-anchor" href="#_5-1-lam-trong-v1-—-theo-module-bounded-context" aria-label="Permalink to &quot;5.1 Làm trong v1 — theo module (bounded context)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Module</th><th>Nội dung chính</th><th>Milestone</th></tr></thead><tbody><tr><td>M1</td><td>Identity &amp; KYC</td><td>Đăng ký/đăng nhập email+password, JWT access/refresh, hồ sơ, xác minh CCCD (ảnh + duyệt thủ công bởi ADMIN)</td><td>MS1</td></tr><tr><td>M2</td><td>Housing (tin đăng)</td><td>Dự án NOXH (seed/admin tạo), chủ nhà tạo tin → duyệt → đăng bán; ảnh + tài liệu pháp lý; ràng buộc sổ hồng/đỏ ↔ tài khoản</td><td>MS1</td></tr><tr><td>M3</td><td>Admin Moderation</td><td>Queue duyệt KYC, duyệt tin, quản lý users/dự án, suspend tài khoản, audit log</td><td>MS1</td></tr><tr><td>M4</td><td>Auction</td><td>ADMIN tạo &amp; công bố phiên (1 phiên = 1 căn), đăng ký tham gia + đặt cọc, đấu giá công khai có bước giá &amp; anti-sniping, kết quả, xử lý vi phạm</td><td>MS2</td></tr><tr><td>M5</td><td>Payments</td><td>Tích hợp 1 cổng thanh toán VN (VNPay — pending OQ-2) + fallback chuyển khoản thủ công do ADMIN xác nhận; hoàn cọc tự động; webhook idempotent</td><td>MS2</td></tr><tr><td>M6</td><td>Settlement Orders</td><td>Đơn thanh toán phần còn lại cho người trúng (kèm phí đấu giá), hạn 24h, đối trừ cọc, xử lý quá hạn (forfeit)</td><td>MS2</td></tr><tr><td>M7</td><td>Packages (VIP)</td><td>Gói FREE / VIP_STANDARD / VIP_PRO hạn 30 ngày; mua → thanh toán → kích hoạt → hạn mức tin đăng + quyền ưu tiên hiển thị</td><td>MS3</td></tr><tr><td>M8</td><td>Viewing</td><td>Người mua đặt lịch xem nhà, chủ nhà/Ops xác nhận</td><td>MS3</td></tr><tr><td>M9</td><td>Notifications</td><td>In-app + email cho các quyết định nghiệp vụ (duyệt, kết quả, nhắc lịch, thanh toán)</td><td>MS3</td></tr><tr><td>M10</td><td>Admin Dashboard</td><td>Số liệu vận hành: users, tin, phiên, GMV, ticket SLA; export CSV</td><td>MS3</td></tr></tbody></table><p>Frontend v1: <strong>Next.js web (desktop + responsive mobile-web)</strong>. API contract đủ để mobile Flutter (repo <code>mobile/</code>) dùng lại — <strong>nhưng phát hành app mobile không thuộc v1</strong> (đưa vào backlog v2, xem docs/10 §7).</p><h3 id="_5-2-khong-lam-trong-v1-non-goals" tabindex="-1">5.2 Không làm trong v1 (Non-Goals) <a class="header-anchor" href="#_5-2-khong-lam-trong-v1-non-goals" aria-label="Permalink to &quot;5.2 Không làm trong v1 (Non-Goals)&quot;">​</a></h3><ul><li>❌ <strong>Mọi tính năng AI</strong> — đề xuất căn hộ theo hành vi, định giá tự động (AVM), phân tích ảnh/hồ sơ bằng AI. <strong>Để nguyên cho v2.</strong> Đây là chỉ đạo trực tiếp của người dùng (2026-10-09).</li><li>❌ Đăng nhập bằng số điện thoại + OTP SMS (v1 email + password; OTP là hướng v1.1 — OQ-5).</li><li>❌ Vay mua nhà / tích hợp ngân hàng, thẩm định tín dụng.</li><li>❌ Chủ nhà tự mở phiên đấu giá (v1 phiên do ADMIN vận hành — BR-AU-01).</li><li>❌ Đấu giá nhiều căn gộp 1 phiên (v1: 1 phiên = 1 căn).</li><li>❌ Chat trong ứng dụng, review/đánh giá, hệ thống affiliate/môi giới đa cấp.</li><li>❌ Thanh toán quốc tế, hóa đơn điện tử (OQ-6, chờ pháp chế+thuế).</li><li>❌ Xác minh CCCD tự động qua API nhà nước (v1 duyệt thủ công).</li><li>❌ Mobile app GA (Flutter repo có sẵn nhưng đóng băng đến khi API ổn định).</li><li>❌ Quên mật khẩu self-service (v1: CS reset + ADMIN audit — UC-01 AF-3; reset email là v1.1, xem backlog docs/10 §7).</li></ul><h3 id="_5-3-pham-vi-nghiep-vu-business-scope" tabindex="-1">5.3 Phạm vi nghiệp vụ (business scope) <a class="header-anchor" href="#_5-3-pham-vi-nghiep-vu-business-scope" aria-label="Permalink to &quot;5.3 Phạm vi nghiệp vụ (business scope)&quot;">​</a></h3><ul><li>Chỉ giao dịch <strong>nhà ở xã hội</strong> trên nền tảng; pháp lý căn nhà phải là sổ hồng/đỏ đứng tên chủ sở hữu khớp CCCD.</li><li>Nền tảng là <strong>bên tổ chức đấu giá</strong> (An Phuc trực tiếp vận hành) — không chỉ là bảng tin; do đó chịu trách nhiệm quy chế, audit, tiền cọc.</li><li>Giá bán lại NOXH phải tuân thủ <strong>giá trần do tỉnh quy định</strong> theo dự án — hệ thống enforce qua <code>housing_projects.resale_price_cap_m2</code> (điều chỉnh theo pháp lý: OQ-4).</li></ul><hr><h2 id="_6-quy-tac-kinh-doanh-tong-quan" tabindex="-1">6. Quy tắc kinh doanh tổng quan <a class="header-anchor" href="#_6-quy-tac-kinh-doanh-tong-quan" aria-label="Permalink to &quot;6. Quy tắc kinh doanh tổng quan&quot;">​</a></h2><p>Chi tiết đầy đủ, mã hóa từng quy tắc: <strong>docs/08 (Business Rules + Permission Matrix)</strong> — đó là nguồn chân lý cho developer. Tóm tắt nhóm quy tắc:</p><table tabindex="0"><thead><tr><th>Nhóm</th><th>Ví dụ quy tắc tiêu biểu</th></tr></thead><tbody><tr><td>BR-IDT</td><td>1 CCCD ↔ 1 tài khoản; email unique; khóa tạm thời khi đấu giá đang diễn ra</td></tr><tr><td>BR-KYC</td><td>CCCD 12 số + ảnh 2 mặt + tên/DOB khớp; ADMIN duyệt ≤ 48h; tối đa 3 lần nộp/30 ngày</td></tr><tr><td>BR-HS</td><td>Chỉ chủ sổ đăng bán; số sổ unique toàn sàn; giá m² ≤ cap dự án; 3–15 ảnh; tin từ chối sửa tối đa 5 lần/30 ngày</td></tr><tr><td>BR-AU</td><td>Phiên do ADMIN tạo; công bố trước ≥ 7 ngày; đóng đăng trước 24h; cọc 5% giá khởi điểm; bước giá ≥ 1%; bid không rút; anti-snipe +60s; không bid → FAILED; người trúng phải trả trong 24h</td></tr><tr><td>BR-PAY</td><td>Hoàn cọc 3 ngày làm việc cho người thua; vi phạm hạn thanh toán → forfeit cọc + treo quyền đấu giá</td></tr><tr><td>BR-PKG</td><td>FREE 2 tin; VIP_STANDARD 10 tin; VIP_PRO 50 tin; gia hạn cộng dồn; không hoàn giữa chu kỳ (v1)</td></tr><tr><td>BR-VW</td><td>Đặt lịch trước ≥ 24h; tối đa 3 lịch chờ/user</td></tr></tbody></table><p><strong>Nguyên tắc vàng</strong>: mọi quy tắc có ID (BR-xx-yy), developer chỉ được implement đúng ID được reference trong story — không tự suy đoán.</p><hr><h2 id="_7-mo-hinh-doanh-thu-v1" tabindex="-1">7. Mô hình doanh thu (v1) <a class="header-anchor" href="#_7-mo-hinh-doanh-thu-v1" aria-label="Permalink to &quot;7. Mô hình doanh thu (v1)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nguồn</th><th>Cơ chế</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Phí đấu giá</td><td><code>%</code> trên giá trúng (mặc định 1,5%, cấu hình mỗi phiên), gộp vào settlement order</td><td>BR-AU-14</td></tr><tr><td>Gói VIP</td><td>500.000đ/30 ngày (VIP_STANDARD), 1.500.000đ/30 ngày (VIP_PRO) — hạn mức tin + ưu tiên hiển thị</td><td>giá khởi điểm, chờ ban điều hành duyệt (OQ-8)</td></tr><tr><td>Đăng tin FREE</td><td>2 tin active, không phí</td><td>mồi nguồn cung</td></tr></tbody></table><h2 id="_8-milestones-đieu-kien-nghiem-thu-cap-chuong-trinh" tabindex="-1">8. Milestones &amp; điều kiện nghiệm thu cấp chương trình <a class="header-anchor" href="#_8-milestones-đieu-kien-nghiem-thu-cap-chuong-trinh" aria-label="Permalink to &quot;8. Milestones &amp; điều kiện nghiệm thu cấp chương trình&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Milestone</th><th>Thời lượng</th><th>Nội dung</th><th>Gate để đi tiếp</th></tr></thead><tbody><tr><td><strong>MS1 — Marketplace có kiểm duyệt</strong></td><td>Tuần 1–6</td><td>Identity thật (DB), KYC, Housing CRUD + duyệt, public browsing; chưa có tiền</td><td>20 tin LISTED bởi chủ nhà thật (pilot); e2e pass 100%; không P0</td></tr><tr><td><strong>MS2 — Đấu giá + Tiền</strong></td><td>Tuần 7–12</td><td>Auction, deposit, bidding, settlement, gateway</td><td>1 phiên dry-run end-to-end với tiền thật (giá trị tượng trưng); reconciliation pass</td></tr><tr><td><strong>MS3 — Monetization + Vận hành</strong></td><td>Tuần 13–16</td><td>Packages VIP, viewing, notifications, admin dashboard, hardening</td><td>GA gate: docs/09 suite pass 100%, CS trained, rollback runbook</td></tr><tr><td><strong>GA</strong></td><td>Tuần 17</td><td>Mở public theo tiến trình 20% → 100% feature flags</td><td>xem docs/09 §5</td></tr></tbody></table><h2 id="_9-rui-ro-kinh-doanh-chinh" tabindex="-1">9. Rủi ro kinh doanh chính <a class="header-anchor" href="#_9-rui-ro-kinh-doanh-chinh" aria-label="Permalink to &quot;9. Rủi ro kinh doanh chính&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rủi ro</th><th>Xác suất</th><th>Tác động</th><th>Giảm thiểu</th></tr></thead><tbody><tr><td>Pháp lý: quy chế đấu giá NOXH chưa được cơ quan xác nhận</td><td>Medium</td><td>High</td><td>Pháp chế review trước MS2; v1 định vị &quot;đấu giá niêm yết nội bộ sàn&quot; — cần ý kiến luật sư (OQ-4)</td></tr><tr><td>Nguồn cung lạnh (chủ nhà không đăng)</td><td>High</td><td>High</td><td>Ops mời tay 50 căn pilot từ dự án trọng điểm; FREE tier; KPI cho đội sales</td></tr><tr><td>Người trúng bỏ cọc (thị trường ảo, không tiền thật)</td><td>Medium</td><td>High</td><td>Cọc 5% forfeit + treo tài khoản (BR-AU/BR-PAY); lọc KYC</td></tr><tr><td>Cổng thanh toán chậm tích hợp</td><td>Medium</td><td>High</td><td>Fallback chuyển khoản thủ công + ADMIN xác nhận (đã thiết kế trong flow docs/04)</td></tr><tr><td>Email không đến tay người dùng (spam/SMTP chưa cọc cấu hình) — mất kênh nhắc thanh toán 24h</td><td>Medium</td><td>High</td><td>Chọn provider sớm (SRS §2), DKIM/SPF trước MS2; mọi email quan trọng có bản in-app; SMTP là OQ-10</td></tr><tr><td>Dữ liệu hiện trạng (xlsx) chứa quy tắc chưa biết</td><td>Medium</td><td>Medium</td><td>OQ-0 blocking trước khi BRD Approved</td></tr></tbody></table><h2 id="_10-open-questions-blocking-phai-xong-truoc-dev-ms-tuong-ung" tabindex="-1">10. Open Questions (blocking = phải xong trước dev MS tương ứng) <a class="header-anchor" href="#_10-open-questions-blocking-phai-xong-truoc-dev-ms-tuong-ung" aria-label="Permalink to &quot;10. Open Questions (blocking = phải xong trước dev MS tương ứng)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Câu hỏi</th><th>Owner</th><th>Deadline</th><th>Blocking</th></tr></thead><tbody><tr><td>OQ-0</td><td>Bóc tách file &quot;Hiện trạng phân mồi, web quản trị kinh doanh.xlsx&quot; → hợp nhất quy tắc hiện trạng vào docs/08</td><td>BA/Ops + PM</td><td>trước khi BRD Approved</td><td>BRD</td></tr><tr><td>OQ-1</td><td>Chốt DB + ORM (Postgres + TypeORM vs Prisma) khi dựng adapter đầu tiên</td><td>Tech Lead</td><td>tuần 1</td><td>MS1</td></tr><tr><td>OQ-2</td><td>Cổng thanh toán: VNPay vs Payoo vs ZaloPay (hợp đồng, phí, sandbox)</td><td>Finance + Tech Lead</td><td>tuần 5</td><td>MS2</td></tr><tr><td>OQ-3</td><td>Lưu trữ ảnh/hồ sơ: S3-compatible tự host hay Cloudflare R2</td><td>DevOps</td><td>tuần 1</td><td>MS1</td></tr><tr><td>OQ-4</td><td>Ý kiến pháp chế: giá trần bán lại NOXH theo dự án + tư cách &quot;bên đấu giá&quot; của An Phuc (Luật Đấu giá 2025? Luật Nhà ở 2023, NĐ100/2024)</td><td>Pháp chế</td><td>tuần 4</td><td>MS2 scope</td></tr><tr><td>OQ-5</td><td>nhà cung cấp SMS OTP cho v1.1 (chọn sớm để chuẩn bị data model số điện thoại)</td><td>Tech Lead</td><td>tuần 8</td><td>v1.1</td></tr><tr><td>OQ-6</td><td>Hóa đơn điện tử cho phí đấu giá/VIP</td><td>Kế toán + Pháp chế</td><td>tuần 10</td><td>MS3/GA</td></tr><tr><td>OQ-7</td><td>Danh sách 50 căn pilot + data seed dự án NOXH (10 dự án đầu tiên)</td><td>Ops</td><td>tuần 3</td><td>MS1</td></tr><tr><td>OQ-8</td><td>Bảng giá gói VIP chính thức</td><td>Ban điều hành</td><td>tuần 12</td><td>MS3</td></tr><tr><td>OQ-9</td><td>Figma cho 20 màn v1 (tokens + prototype, điều kiện handoff docs/05 §8)</td><td>Design Lead</td><td>tuần 4</td><td>MS1 (FE)</td></tr><tr><td>OQ-10</td><td>Email provider + domain DKIM/SPF (Resend/SES) để NTF v1 không rơi spam</td><td>DevOps</td><td>tuần 5</td><td>MS2</td></tr></tbody></table><h2 id="_11-đieu-kien-phe-duyet-brd" tabindex="-1">11. Điều kiện phê duyệt BRD <a class="header-anchor" href="#_11-đieu-kien-phe-duyet-brd" aria-label="Permalink to &quot;11. Điều kiện phê duyệt BRD&quot;">​</a></h2><ul><li>[ ] OQ-0 hoàn tất, quy tắc hiện trạng hợp nhất</li><li>[ ] 5+5 phỏng vấn người mua/bán (Discovery) xác nhận pain top-3: pháp lý, giá, cọc</li><li>[ ] Pháp chế sign-off §5.3 và OQ-4 plan</li><li>[ ] Ban điều hành duyệt mô hình thu §7 + milestones §8</li></ul>',48)])])}const p=n(a,[["render",e]]);export{l as __pageData,p as default};
